function localizedRoleProfile(profile, locale, categoryId) {
  const copy = CATEGORY_COPY[categoryId]?.[locale] || CATEGORY_COPY[categoryId]?.en || CATEGORY_COPY["business-operations"].en;
  const userLabel = locale === "zh" ? "用户" : "User";
  const name = profile.name;
  const boundary = profile.boundary || copy.checks[0];
  const method = profile.method || copy.workflow[1];
  const personality = locale === "zh"
    ? `${name}会先核对事实、范围和风险，再推进可执行的下一步。${boundary}`
    : `${name} checks facts, scope, and risk before moving to an executable next step. ${boundary}`;
  const exampleSeparator = locale === "zh" ? "；" : "; ";
  const canonical = {
    schemaVersion: 3,
    name,
    description: profile.summary,
    personality,
    scenario: profile.use,
    firstMessage: locale === "zh" ? `${copy.required}。${profile.summary}` : `${copy.required}. ${profile.summary}`,
    exampleDialogue: locale === "zh"
      ? `${userLabel}: ${profile.use}\n${name}: ${copy.workflow[0]}。${method}。`
      : `${userLabel}: ${profile.use}\n${name}: ${copy.workflow[0]}. ${method}.`,
    creatorNotes: `${method} ${boundary} ${copy.checks.join(exampleSeparator)}`,
    tags: [...profile.tags],
  };
  const outputStep = locale === "zh"
    ? `形成${profile.output}`
    : `Produce ${profile.output}`;
  const artifactCheck = locale === "zh"
    ? `${profile.output}中的事实、数字、责任和限制可追溯。`
    : `Facts, numbers, ownership, and limits in ${profile.output} are traceable.`;
  return {
    name,
    tagline: profile.tagline,
    category: copy.category,
    summary: profile.summary,
    suitableFor: [profile.use],
    requiredInputs: [profile.input, copy.required],
    workflow: [copy.workflow[0], method, outputStep, copy.workflow[3]],
    deliverables: [profile.output, locale === "zh" ? "风险、取舍和下一步清单" : "Risk, trade-off, and next-step list"],
    qualityChecks: [artifactCheck, ...copy.checks],
    boundaries: [boundary, locale === "zh" ? "缺少关键材料时明确标注未知，不用猜测补全事实。" : "When critical material is missing, label it unknown instead of filling facts by guesswork."],
    tags: [...profile.tags],
    canonical,
  };
}

function industryRole(id, categoryId, editorialOrder, profile) {
  return {
    id,
    version: 1,
    categoryId,
    editorialOrder,
    featured: false,
    locales: {
      "zh-CN": localizedRoleProfile(profile.zh, "zh", categoryId),
      en: localizedRoleProfile(profile.en, "en", categoryId),
    },
  };
}

